const order = $('On WooCommerce Order Created').first().json || {};
const cfg = $('Store Configuration').first().json || {};
const rawPhone = String(order.billing?.phone || order.shipping?.phone || '').trim();
const cleanPhone = rawPhone.replace(/\D/g, '');
if (cleanPhone.length < 8) return [];

const totalAmount = Number(order.total || 0);
const currency = String(order.currency || 'USD').toUpperCase();
const paymentMethod = String(order.payment_method || '').toLowerCase();
const isCod = paymentMethod === String(cfg.codPaymentMethod || 'cod').toLowerCase();
const addr = order.shipping?.address_1 ? order.shipping : (order.billing || {});
const shippingAddress = [addr.address_1, addr.city, addr.postcode, addr.country].filter(Boolean).join(', ');
const itemsSummary = (order.line_items || []).slice(0, 4).map((li) => `${li.quantity}x ${li.name}`).join(', ');
const reminderHours = Number(cfg.codReminderHours || 4);
const reminderDueAt = new Date(Date.now() + reminderHours * 3600 * 1000).toISOString();

return [{
  json: {
    orderId: String(order.id || ''),
    orderNumber: '#' + String(order.number || order.id || ''),
    customerName: String(order.billing?.first_name || order.shipping?.first_name || 'there').trim(),
    email: String(order.billing?.email || '').trim(),
    cleanPhone,
    totalFormatted: `${totalAmount.toFixed(2)} ${currency}`,
    paymentMethod,
    isCod,
    shippingAddress: shippingAddress || 'Address on file',
    itemsSummary: itemsSummary || 'Your order items',
    reminderDueAt,
    storeName: cfg.storeName,
    spreadsheetId: cfg.spreadsheetId,
    slackOpsChannelId: cfg.slackOpsChannelId,
  },
}];

const row = $input.first()?.json;
if (!row || !row.orderId || row.status !== 'Pending COD') return [];
const ev = $('When Customer Votes on COD Poll').first().json || {};
const cfg = $('Vote Handler Configuration').first().json || {};
const selected = ev.vote?.selectedOptionIndices;
if (!Array.isArray(selected) || selected.length === 0) return [];
const idx = Number(selected[0]);
if (idx < 0 || idx > 2) return [];
const decisions = ['confirmed', 'address_change', 'cancelled'];
return [{
  json: {
    ...row,
    chatId: String(ev.chat?.id || row.phone),
    decision: decisions[idx],
    storeName: cfg.storeName,
    spreadsheetId: cfg.spreadsheetId,
    slackOpsChannelId: cfg.slackOpsChannelId,
  },
}];

const order = $('On WooCommerce Order Updated').first().json || {};
const cfg = $('Shipment Update Configuration').first().json || {};
if (String(order.status || '').toLowerCase() !== 'completed') return [];
const cleanPhone = String(order.billing?.phone || order.shipping?.phone || '').replace(/\D/g, '');
if (cleanPhone.length < 8) return [];
return [{
  json: {
    orderId: String(order.id || ''),
    orderNumber: '#' + String(order.number || order.id || ''),
    customerName: String(order.billing?.first_name || 'there').trim(),
    cleanPhone,
    storeName: cfg.storeName,
    spreadsheetId: cfg.spreadsheetId,
  },
}];

const cfg = $('Reminder Configuration').first().json || {};
const now = Date.now();
const overdue = [];
for (const item of $input.all()) {
  const row = item.json;
  if (!row || !row.orderId || !row.phone) continue;
  if (row.status !== 'Pending COD' || row.reminderSent === 'Yes') continue;
  const dueMs = Date.parse(String(row.reminderDueAt || ''));
  if (!Number.isFinite(dueMs) || dueMs > now) continue;
  overdue.push({ json: { ...row, storeName: cfg.storeName, spreadsheetId: cfg.spreadsheetId, slackOpsChannelId: cfg.slackOpsChannelId } });
}
return overdue;
